 912→// ── Reusable position tile selector ─────────────────────────────────────────
 913→const PositionTile = memo(function PositionTile({
 914→  value,
 915→  label,
 916→  selected,
 917→  disabled,
 918→  onSelect,
 919→  children,
 920→}: {
 921→  value: string;
 922→  label: string;
 923→  selected: boolean;
 924→  disabled: boolean;
 925→  onSelect: (v: string) => void;
 926→  children: React.ReactNode;
 927→}) {
 928→  const handleClick = useCallback(() => {
 929→    if (!disabled) onSelect(value);
 930→  }, [disabled, onSelect, value]);
 931→
 932→  return (
 933→    <button
 934→      type="button"
 935→      aria-pressed={selected}
 936→      onClick={handleClick}
 937→      disabled={disabled}
 938→      onKeyDown={(e) => {
 939→        if ((e.key === "Enter" || e.key === " ") && !disabled) {
 940→          e.preventDefault();
 941→          onSelect(value);
 942→        }
 943→      }}
 944→      style={{
 945→        flex: 1,
 946→        minWidth: 100,
 947→        appearance: "none",
 948→        WebkitAppearance: "none",
 949→        border: "none",
 950→        borderRadius: "var(--p-border-radius-200)",
 951→        padding: "var(--p-space-300)",
 952→        cursor: disabled ? "not-allowed" : "pointer",
 953→        opacity: disabled ? 0.5 : 1,
 954→        textAlign: "center",
 955→        outline: "none",
 956→        transition: "box-shadow 0.15s ease, background 0.15s ease",
 957→        background: selected
 958→          ? "var(--p-color-bg-surface-selected)"
 959→          : "var(--p-color-bg-surface)",
 960→        boxShadow: selected
 961→          ? "0 0 0 2px var(--p-color-border-emphasis)"
 962→          : "0 0 0 1px var(--p-color-border)",
 963→        fontFamily: "inherit",
 964→        color: "inherit",
 965→        fontSize: "inherit",
 966→      }}
 967→    >
 968→      <BlockStack gap="100" inlineAlign="center">
 969→        {children}
 970→        <Text as="p" variant="bodySm" fontWeight={selected ? "semibold" : "regular"}>
 971→          {label}
 972→        </Text>
 973→      </BlockStack>
 974→    </button>
 975→  );
