 346→  // ── Countdown timer functions ─────────────────────────────────────────────────
 347→  function getCountdownData(cutoffTime) {
 348→    if (!cutoffTime) return null;
 349→    var parts = cutoffTime.split(':');
 350→    var cutoffHr = parseInt(parts[0], 10);
 351→    var cutoffMin = parseInt(parts[1] || '0', 10);
 352→    var now = new Date();
 353→    var cutoff = new Date();
 354→    cutoff.setHours(cutoffHr, cutoffMin, 0, 0);
 355→    var diff = cutoff - now;
 356→    if (diff <= 0) return { passed: true, hours: 0, minutes: 0 };
 357→    var hours = Math.floor(diff / 3600000);
 358→    var minutes = Math.floor((diff % 3600000) / 60000);
 359→    return { passed: false, hours: hours, minutes: minutes };
 360→  }
 361→
 362→  function buildCountdownHtml(cutoffTime, widgetId) {
 363→    var cd = getCountdownData(cutoffTime);
 364→    if (!cd) return '';
 365→    var colorClass, text;
 366→    if (cd.passed) {
 367→      colorClass = 'zcc-countdown--passed';
 368→      text = 'Order now for next business day dispatch';
 369→    } else {
 370→      var totalMinutes = cd.hours * 60 + cd.minutes;
 371→      if (totalMinutes > 180) colorClass = 'zcc-countdown--green';
 372→      else if (totalMinutes > 60) colorClass = 'zcc-countdown--amber';
 373→      else colorClass = 'zcc-countdown--red';
 374→      text = 'Order within <strong>' + cd.hours + 'h ' + cd.minutes + 'm</strong> for same-day dispatch';
 375→    }
 376→    return '<div class="zcc-countdown ' + colorClass + '" id="' + widgetId + '-countdown">' + ICONS.clock + '<span>' + text + '</span></div>';
 377→  }
 378→
 379→  function startCountdownUpdater(widgetId, cutoffTime) {
 380→    if (!cutoffTime) return;
 381→    setInterval(function() {
 382→      var el = document.getElementById(widgetId + '-countdown');
 383→      if (!el) return;
 384→      var cd = getCountdownData(cutoffTime);
 385→      if (!cd) return;
 386→      if (cd.passed) {
 387→        el.className = 'zcc-countdown zcc-countdown--passed';
 388→        el.innerHTML = ICONS.clock + '<span>Order now for next business day dispatch</span>';
 389→        return;
 390→      }
 391→      var totalMinutes = cd.hours * 60 + cd.minutes;
 392→      var cls = totalMinutes > 180 ? 'zcc-countdown--green' : totalMinutes > 60 ? 'zcc-countdown--amber' : 'zcc-countdown--red';
 393→      el.className = 'zcc-countdown ' + cls;
 394→      el.innerHTML = ICONS.clock + '<span>Order within <strong>' + cd.hours + 'h ' + cd.minutes + 'm</strong> for same-day dispatch</span>';
 395→    }, 30000);
 396→  }
