 573→    if (!inp || !btn || !res) return;
 574→
 575→    function normalizeZip(raw) {
 576→      var z = raw.trim().toUpperCase();
 577→      z = z.replace(/\s+/g, '');        // collapse all spaces (UK: SW1A 2AA → SW1A2AA)
 578→      z = z.replace(/-\d{4}$/, '');     // strip US ZIP+4 suffix (90210-1234 → 90210)
 579→      return z;
 580→    }
 581→
 582→    // Store the original button HTML so we can restore it exactly after loading
 583→    var btnOriginalHtml = btn.innerHTML;
 584→
 585→    function setBtnLoading(loading) {
 586→      btn.disabled = loading;
 587→      if (loading) {
 588→        btn.classList.add('zcc-btn--loading');
 589→        // Replace entire button content with a lone spinner — no text overlap
 590→        btn.innerHTML = '<span class="zcc-spinner" aria-hidden="true"></span>';
 591→      } else {
 592→        btn.classList.remove('zcc-btn--loading');
 593→        // Restore original icon + label markup
 594→        btn.innerHTML = btnOriginalHtml;
 595→        // Keep button text in sync with config (merchant may have customised it)
 596→        var labelEl = btn.querySelector('.zcc-btn-label');
 597→        if (labelEl) labelEl.textContent = cfg.buttonText;
 598→      }
 599→    }
