 601→    function checkZip() {
 602→      var zip = normalizeZip(inp.value);
 603→      inp.value = zip;  // Update the input field to show the normalized value (clean UX)
 604→      if (!zip) { inp.focus(); return; }
 605→
 606→      setBtnLoading(true);
 607→      res.innerHTML = "";
