 613→        .then(function (r) {
 614→          if (!r.ok) {
 615→            // Non-2xx: try to parse JSON error body, fall back to status text
 616→            return r.json().catch(function() {
 617→              return { error: 'Server error (' + r.status + ')' };
 618→            });
